// GBA WAT backend: statically recompile a whole GBA ROM into a wasmcart that
// runs on mGBA 0.11's clock, frame-exact against romdev's mGBA core.
//
// The CPU is cpu.js (mGBA's ARM7TDMI handlers, cycle accounting included),
// the system is sys.js (bus, scheduler, video timing, timers, DMA, FIFOs,
// save chips, interrupts, BIOS calls), the BIOS is mGBA's own HLE BIOS image
// executed as ARM code, and the picture is video.js's scanline renderer.
//
// Code is compiled ahead of time. THUMB: all 65536 opcodes get a static arm,
// generated by the same generator the interpreter uses with the opcode as a
// compile-time constant, so every Thumb instruction the cart can execute (ROM,
// BIOS, or code copied into IWRAM/EWRAM) runs compiled code. ARM: every word
// of the ROM and of the BIOS is compiled (a computed jump can land anywhere,
// and code cannot be told from data); ROM and BIOS addresses index tables of
// arm ids (ATAB/BTAB), identical words share one arm, and ARM code in RAM is
// looked up by its word in AHASH. A word found nowhere goes to the
// interpreter, which is also the oracle; PROBE counts compiled and
// interpreted steps.
//
// The frame loop is mGBA's _GBACoreRunFrame: run until the video frame
// counter moves (VBlank start, line 160). romdev's LibretroHost runs five
// settle frames on mGBA during loadMedia; its WasmcartHost runs one
// wc_render. The first wc_render therefore runs four extra warm-up frames, so
// cart frame N and reference frame N are the same emulated frame.
//
// Output is the same WAT, character for character, as the earlier Python
// emitter: that differential is the port's acceptance gate.
// The module is 1-3 GB of text for a 4-8 MB ROM, so emitWat yields chunks and
// never holds the module as one string.
//
// mGBA-derived data (decoder tables, HLE BIOS, waitstates, overrides, musl
// exp2f, the affine trig table) is mgba-data.json, generated once by
// scripts/recompile-gen/gba-mgba.mjs from romdev's pinned mGBA checkout.
//
// Plain JS ESM + JSDoc.

import { createHash } from "node:crypto";
import { crc32 } from "node:zlib";
import {
  ARM_TABLE, THUMB_TABLE, MGBA_DATA, G, setRegs, armIndex, arm, thumb, localDecls,
} from "./cpu.js";
import {
  sysWat, swiWat, NEV, EV_VIDEO, EV_FRAME, EV_SAMPLE, VIDEO_TOTAL_LENGTH,
  SAVE_AUTODETECT, SAVE_FORCE_NONE, SAVE_SRAM, SAVE_FLASH512, SAVE_FLASH1M, SAVE_EEPROM,
  SAVE_EEPROM512, SAVE_SRAM512,
} from "./sys.js";
import * as video from "./video.js";
import { gpioWat, HW_RTC } from "./gpio.js";
import { RTC_CLOCK } from "../../recompile-section.js";
import { audioLayout, audioWat, audioData, audioInfoWat, audioSection } from "./audio.js";
import { assertHostSpans, WC_ABI_VERSION } from "../cart-abi.js";

export const platforms = ["gba"];
/** loadMedia platform id of the reference core */
export const REFERENCE = "gba";
export const REFERENCE_CORE = "mgba";

/** + the 1 frame romdev's WasmcartHost settles = the 5 LibretroHost settles on mGBA */
export const WARMUP_FRAMES = 4;
/** trace ring entries (21 words each) */
export const TRACE_CAP = 1 << 20;
export const TRACE_ENTRY = 84;
/** ARM/Thumb static arms per br_table shard function */
const SHARD = 512;

const SAVE_NAMES = {
  [SAVE_AUTODETECT]: "autodetect", [SAVE_FORCE_NONE]: "none", [SAVE_SRAM]: "sram",
  [SAVE_FLASH512]: "flash512", [SAVE_FLASH1M]: "flash1m", [SAVE_EEPROM]: "eeprom",
  [SAVE_EEPROM512]: "eeprom512", [SAVE_SRAM512]: "sram512",
};

/**
 * @typedef {object} GbaOptions
 * @property {boolean} [interp]  build WITHOUT static arms: every instruction
 *   runs through the interpreter (the oracle build; small and slow)
 * @property {'positional'|'byName'} [buttons='positional']  pad reading.
 *   positional: the east face button (WC_BTN_B) is the GBA's A and south
 *   (WC_BTN_A) is B, matching the wasmcart host's positional translation.
 *   byName: WC_BTN_A is the GBA's A (the earlier emitter's reading; the only
 *   difference in the emitted text, used by the differential gate)
 * @property {object} [stats]  filled by emitWat: arm counts
 * @property {number|string|null} [breakThumb]  DEBUG / MUST-FAIL CONTROL:
 *   compile this one Thumb opcode's static arm as a no-op (hex string or
 *   number), so a differential run has to report a divergence. Never set
 *   for a real build. (0x1C20 diverges at
 *   frame 1 on every verified cart.)
 */

/** @param {Uint8Array|ArrayBuffer|Buffer} b @returns {Uint8Array} */
function toBytes(b) {
  if (b instanceof Uint8Array) return b;
  if (b instanceof ArrayBuffer) return new Uint8Array(b);
  throw new TypeError("gba recompile: rom must be a Uint8Array/Buffer");
}

/** @param {Uint8Array} img @param {string} s */
function hasAscii(img, s) {
  return Buffer.from(img.buffer, img.byteOffset, img.byteLength).indexOf(s, 0, "latin1") >= 0;
}

/**
 * The save chip the cart's library string names (Nintendo's SDK embeds
 * EEPROM_V / SRAM_V / SRAM_F_V / FLASH_V / FLASH512_V / FLASH1M_V). Only
 * informational: mGBA autodetects the chip at run time from the first access
 * (unless its override table names it), and so does the cart.
 * @param {Uint8Array} img
 */
function saveLibrary(img) {
  for (const [tag, type] of [["EEPROM_V", "eeprom"], ["SRAM_F_V", "sram"], ["SRAM_V", "sram"],
    ["FLASH1M_V", "flash1m"], ["FLASH512_V", "flash512"], ["FLASH_V", "flash512"]]) {
    if (hasAscii(img, tag)) return { tag, type };
  }
  return null;
}

/**
 * mGBA's GBAOverrideApplyDefaults: the ROM-hack rule (an image whose header
 * matches but whose CRC32 is not a known dump gets FLASH1M, the RTC and
 * vbaBugCompat), else GBAOverrideFind: the override table, then the 'F'
 * game-code rule (id starting with 'F' saves to EEPROM).
 * @param {string} code
 * @param {Uint8Array} [img] the ROM image (for the ROM-hack rule)
 * @returns {{savetype: number, hardware: number, idleLoop: number|null, vba?: boolean, source: string}}
 */
function findOverride(code, img) {
  const rule = MGBA_DATA.romHackRule;
  if (img && rule.matches.some((m) => strncmpAt(img, m.offset, Buffer.from(m.hex, "hex"), m.n))
      && !rule.knownCrc32.includes(crc32(img))) {
    return { savetype: rule.savetype, hardware: rule.hardware, idleLoop: null, vba: rule.vbaBugCompat, source: "mGBA ROM-hack rule" };
  }
  const o = MGBA_DATA.overrides[code];
  if (o) return { savetype: o.savetype, hardware: o.hardware ?? 0, idleLoop: o.idleLoop, source: "mGBA override table" };
  if (code[0] === "F") return { savetype: SAVE_EEPROM, hardware: 0, idleLoop: null, source: "mGBA 'F' game-code rule" };
  return { savetype: SAVE_AUTODETECT, hardware: 0, idleLoop: null, source: "none (runtime autodetect)" };
}

/** strncmp(lit, &img[off], n) == 0 */
function strncmpAt(img, off, lit, n) {
  for (let i = 0; i < n; i++) {
    const a = lit[i] ?? 0, b = off + i < img.length ? img[off + i] : 0;
    if (a !== b) return false;
    if (a === 0) return true;
  }
  return true;
}

const ahashBits = (n) => { let k = 10; while ((1 << k) < 2 * n) k++; return k; };
const ahashSlot = (w, k) => Math.imul(w, 0x9E3779B1) >>> (32 - k);

/** ROM size rounded up to a word. */
const romSpan = (n) => (n + 3) & ~3;
/** @param {number} n */
function romMask(n) { let m = 1; while (m < n) m *= 2; return m - 1; }

/** Every ROM word (image zero-padded to a word) and the 4096 HLE BIOS words. */
function armWords(img) {
  const span = romSpan(img.length);
  const pad = new Uint8Array(span);
  pad.set(img);
  const words = new Uint32Array(pad.buffer, 0, span / 4).slice();
  const bios = new Uint32Array(Uint8Array.from(Buffer.from(MGBA_DATA.hleBios, "base64")).buffer);
  return { words, bios };
}

/** Sorted unique union of two word arrays. */
function uniqueWords(a, b) {
  const all = new Uint32Array(a.length + b.length);
  all.set(a); all.set(b, a.length);
  all.sort();
  let n = 0;
  for (let i = 0; i < all.length; i++) if (i === 0 || all[i] !== all[i - 1]) all[n++] = all[i];
  return all.slice(0, n);
}

/**
 * Linear-memory layout.
 * @param {number} romLen @param {boolean} staticRom @param {number} [nArm] unique ARM words
 */
export function computeLayout(romLen, staticRom, nArm = 0) {
  const [hwend, fb] = video.sizes();
  /** @type {Record<string, number>} */
  const L = { EWRAM: video.EWRAM, IWRAM: video.IWRAM, IO: video.IOREG, PAL: video.PAL,
    VRAM: video.VRAM, OAM: video.OAM, SINTAB: video.SINTAB };
  let a = (hwend + 0xFFF) & ~0xFFF;
  const alloc = (name, size, align = 16) => {
    a = Math.ceil(a / align) * align;
    L[name] = a;
    a += size;
  };
  alloc("BIOS", 0x4000);
  alloc("REGS", 64);
  alloc("BANK", 6 * 28 + 6 * 4);
  alloc("WS", 1024);
  alloc("EVWHEN", 4 * NEV);
  alloc("EVACT", 4 * NEV);
  alloc("DMA", 4 * 40);
  alloc("TIMER", 4 * 16);
  alloc("SAVE", 0x20000);
  alloc("WAVE", 32);
  alloc("VSTALL", 64);
  alloc("CONDLUT", 32);
  alloc("ROMWS", 4);
  alloc("ROMWSS", 8);
  alloc("DMAOFF", 4);
  alloc("PRESCALE", 4);
  alloc("SIOCYC", 16);
  alloc("DEADBEEF", 4);
  alloc("EXP2FTAB", 256, 8);
  alloc("PROBE", 256);
  alloc("CKPT", 128);
  alloc("TRACE", TRACE_CAP * TRACE_ENTRY);
  alloc("ABI", 0x1000);
  if (staticRom) {
    alloc("ATAB", 4 * (romSpan(romLen) / 4), 0x1000);
    alloc("BTAB", 4 * 4096, 0x1000);
    L.AHASH_BITS = ahashBits(nArm);
    alloc("AHASH", 8 << L.AHASH_BITS, 0x1000);
  }
  alloc("ROM", Math.max(romLen, 4), 0x1000);
  L.END = a + romLen;
  // audio.js's block goes after everything else, so no machine address moves
  const A = audioLayout(L);
  L.AUD = A.SINC;
  L.END = A.END_TRACE;
  L.FB = fb;
  // ABI v4: 80 bytes of pads at ABI+0x100 (to +0x150), the clock at +0x180.
  assertHostSpans({ who: "gba", info: L.ABI, input: L.ABI + 0x100, time: L.ABI + 0x180,
    audio: A.OUT, audioBytes: A.STATE - A.OUT, audioWrite: A.STATE,
    others: [["TRACE", L.TRACE, L.ABI - L.TRACE], ["ROM", L.ROM, Math.max(romLen, 4)], ["FB", fb, video.FB_W * video.FB_H * 4], ["EWRAM", L.EWRAM, 0x40000], ["IWRAM", L.IWRAM, 0x8000]] });
  return L;
}

/**
 * The `romdev.recompile` section (recompile-section.js schema v1): where the
 * machine lives in the cart's linear memory and which reference region or
 * CPU field each span mirrors. Rich enough for a per-frame divergence finder
 * (replaces the earlier native-mGBA differ).
 * @param {Record<string, number>} L
 * @param {string} romSha1
 */
function sectionFor(L, romSha1, buttons, hardware = 0) {
  const fields = {};
  for (let i = 0; i < 16; i++) {
    fields[`r${i}`] = { offset: L.REGS + 4 * i, size: 4, ref: { region: "gba_cpu_regs", offset: 4 * i, size: 4 } };
  }
  // written by $checkpoint at the end of every wc_render
  fields.cpsr = { offset: L.CKPT + 68, size: 4, ref: { region: "gba_cpu_regs", offset: 64, size: 4 } };
  fields.spsr = { offset: L.CKPT + 72, size: 4, ref: { region: "gba_cpu_regs", offset: 68, size: 4 } };
  fields.vcount = { offset: L.CKPT + 104, size: 4, ref: { region: "gba_io_regs", offset: 6, size: 2 } };
  return {
    version: 1,
    platform: "gba",
    reference: REFERENCE,
    referenceCore: REFERENCE_CORE,
    romSha1,
    warmupFrames: WARMUP_FRAMES,
    // a GPIO RTC reads the host frame clock; the verifier pins mGBA's time(0)
    // (and localtime's zone, UTC) to the same frames
    ...(hardware & HW_RTC ? { clock: { ...RTC_CLOCK } } : {}),
    // positional: east (WC_BTN_B) is the GBA's A; "byName" only for a cart
    // built with buttons:'byName' (the earlier emitter's reading)
    buttons,
    screen: { origin: [0, 0] },
    framebuffer: { offset: L.FB, width: video.FB_W, height: video.FB_H, format: "argb8888" },
    regions: {
      pal: { offset: L.PAL, length: 0x400, ref: "gba_palette" },
      oam: { offset: L.OAM, length: 0x400, ref: "gba_oam" },
      vram: { offset: L.VRAM, length: 0x18000, ref: "video_ram" },
      ewram: { offset: L.EWRAM, length: 0x40000, ref: "system_ram" },
      iwram: { offset: L.IWRAM, length: 0x8000, ref: "gba_iwram" },
      io: { offset: L.IO, length: 0x400, ref: "gba_io_regs", compare: false,
        note: "the cart's I/O page is its register shadow; read-side registers (VCOUNT, KEYINPUT, timers, IF) are computed on access, so the page is diagnostic, not a gate" },
    },
    vramZero: ["vram"],
    fields,
    audio: audioSection(audioLayout({ END: L.AUD })),
    // the per-step TRACE ring below, in recompile-section.js's `trace` schema
    // (findDiverge level:'instruction'); r0-r15/cpsr are compared per
    // instruction against mGBA's register columns of the same names
    trace: {
      offset: L.TRACE, entries: TRACE_CAP, stride: TRACE_ENTRY,
      cursor: { offset: L.PROBE + 68, mode: "index", writable: true, note: "linear: stops at the capacity" },
      enable: { offset: L.PROBE + 64 },
      pc: { offset: 0 }, clock: { offset: 8, unit: "mTiming master cycles" },
      fields: {
        thumb: { offset: 4 },
        ...Object.fromEntries(Array.from({ length: 15 }, (_, i) => [`r${i}`, { offset: 12 + 4 * i }])),
        r15: { offset: 72, note: "gprs[PC] before the step = exec + width" },
        cpsr: { offset: 76 },
      },
    },
    probe: {
      steps: { offset: L.PROBE + 0, size: 4 },
      trapped: { offset: L.PROBE + 4, size: 4 },
      trappc: { offset: L.PROBE + 8, size: 4 },
      pc: { offset: L.PROBE + 12, size: 4 },
      frameCounter: { offset: L.PROBE + 16, size: 4 },
      compiled: { offset: L.PROBE + 20, size: 4 },
      interpreted: { offset: L.PROBE + 24, size: 4 },
    },
    gba: {
      note: "cart-side diagnostics for a divergence finder; all offsets are linear-memory byte offsets",
      regs: { offset: L.REGS, count: 16, note: "r0-r15; r15 = gprs[ARM_PC] (next instruction + width) between instructions" },
      bank: { offset: L.BANK, note: "6 banks x 7 words (sp, lr, r8-r12), then 6 banked SPSRs" },
      checkpoint: {
        offset: L.CKPT, length: 116,
        note: "written after every wc_render, laid out like the native mGBA trace checkpoint",
        fields: { time: 0, r0: 4, cpsr: 68, spsr: 72, halted: 76, fnvEwram: 80, fnvIwram: 84, fnvVram: 88,
          fnvPal: 92, fnvOam: 96, fnvIo: 100, vcount: 104, cycles: 108, nextEvent: 112 },
        hash: "FNV-1a 32-bit over EWRAM 0x40000, IWRAM 0x8000, VRAM 0x18000, PAL 0x400, OAM 0x400, IO 0x60",
      },
      trace: {
        offset: L.TRACE, capacity: TRACE_CAP, entryBytes: TRACE_ENTRY,
        enable: { offset: L.PROBE + 64, size: 4 }, count: { offset: L.PROBE + 68, size: 4 },
        entry: "pc, thumb, time, r0-r14, r15 (= gprs[PC] before the step), cpsr, vcount (u32 each)",
      },
      scheduler: { when: L.EVWHEN, active: L.EVACT, events: NEV },
      dma: { offset: L.DMA, channels: 4, bytesPerChannel: 40 },
      timers: { offset: L.TIMER, count: 4, bytesPerTimer: 16 },
      save: { offset: L.SAVE, length: 0x20000 },
    },
  };
}

/**
 * Header-derived configuration.
 * @param {Uint8Array} rom
 * @param {GbaOptions} [opts]
 */
export function describe(rom, opts = {}) {
  const img = toBytes(rom);
  const buttons = opts.buttons === "byName" ? "byName" : "positional";
  const ck = `${opts.interp ? 1 : 0}:${buttons}`;
  const cached = DESCRIBE_CACHE.get(img)?.get(ck);
  if (cached) return cached;
  const d = describeUncached(img, opts, buttons);
  if (!DESCRIBE_CACHE.has(img)) DESCRIBE_CACHE.set(img, new Map());
  DESCRIBE_CACHE.get(img).set(ck, d);
  return d;
}

/** describe() results per ROM buffer (emitWat, recompileSection and build.js all ask). */
const DESCRIBE_CACHE = new WeakMap();

function describeUncached(img, opts, buttons) {
  const ascii = (a, n) => Array.from(img.subarray(a, a + n), (c) => (c >= 0x20 && c < 0x7f ? String.fromCharCode(c) : " ")).join("").trimEnd();
  const code = img.length >= 0xB0 ? Buffer.from(img.subarray(0xAC, 0xB0)).toString("latin1") : "";
  const ov = findOverride(code, img);
  const lib = saveLibrary(img);
  const staticRom = !opts.interp;
  let nArm = 0;
  if (staticRom) {
    const { words, bios } = armWords(img);
    nArm = uniqueWords(words, bios).length;
  }
  const L = computeLayout(img.length, staticRom, nArm);
  let refusal = null;
  if (img.length < 0xC0) refusal = `ROM image is ${img.length} bytes; a GBA cart header alone is 192`;
  else if (img.length > 0x2000000) refusal = `ROM image is ${img.length} bytes; the GBA cart space is 32MB`;
  const sha1 = createHash("sha1").update(img).digest("hex");
  return {
    platform: "gba",
    referenceCore: REFERENCE_CORE,
    supported: !refusal,
    refusal,
    title: ascii(0xA0, 12),
    gameCode: code,
    maker: ascii(0xB0, 2),
    version: img.length > 0xBC ? img[0xBC] : 0,
    romSize: img.length,
    romSha1: sha1,
    saveType: SAVE_NAMES[ov.savetype],
    saveTypeSource: ov.source,
    saveLibrary: lib ? `${lib.tag} (${lib.type})` : null,
    idleLoop: ov.idleLoop,
    // mGBA's override HW_* bits; the cart models the GPIO port and the RTC
    hardware: ov.hardware,
    vbaBugCompat: !!ov.vba,
    rtc: (ov.hardware & HW_RTC) !== 0,
    staticArms: staticRom,
    uniqueArmWords: nArm,
    warmupFrames: WARMUP_FRAMES,
    memoryPages: Math.floor((L.END + 0xFFFF) / 0x10000) + 1,
    memory: L,
    buttons,
    layout: sectionFor(L, sha1, buttons, ov.hardware),
  };
}

/**
 * The `romdev.recompile` custom section for this ROM (build.js contract).
 * @param {Uint8Array} rom @param {string} [sha1] @param {GbaOptions} [opts]
 * @returns {{name: string, json: object}}
 */
export function recompileSection(rom, sha1, opts = {}) {
  const d = describe(toBytes(rom), opts);
  if (sha1 && sha1.toLowerCase() !== d.romSha1) throw new Error("gba recompile: sha1 does not match the ROM bytes");
  return { name: "romdev.recompile", json: d.layout };
}

const HEX = Array.from({ length: 256 }, (_, i) => "\\" + i.toString(16).padStart(2, "0"));
/** WAT string escape of bytes (Python's `''.join('\\%02x' % c for c in b)`). */
function watBytes(b) {
  let s = "";
  for (let i = 0; i < b.length; i++) s += HEX[b[i]];
  return s;
}
/** The same, in pieces of `piece` bytes. */
function* watBytesChunks(b, piece = 1 << 18) {
  for (let i = 0; i < b.length; i += piece) {
    const end = Math.min(b.length, i + piece);
    const buf = Buffer.allocUnsafe((end - i) * 3);
    let o = 0;
    for (let j = i; j < end; j++) {
      const v = b[j];
      buf[o++] = 0x5c;
      const hi = v >> 4, lo = v & 15;
      buf[o++] = hi < 10 ? 0x30 + hi : 0x57 + hi;
      buf[o++] = lo < 10 ? 0x30 + lo : 0x57 + lo;
    }
    yield buf.toString("latin1");
  }
}

/** Little-endian bytes of u32 values. */
function u32le(arr) {
  const b = new Uint8Array(arr.length * 4);
  const dv = new DataView(b.buffer);
  for (let i = 0; i < arr.length; i++) dv.setUint32(i * 4, arr[i] >>> 0, true);
  return b;
}

/** Fixed data segments, in the Python emitter's order. */
function dataSegments(L, img) {
  const D = MGBA_DATA;
  const segs = [];
  segs.push([L.BIOS, Buffer.from(D.hleBios, "base64")]);
  const vst = new Uint8Array(64);
  D.vstallLut.forEach((v, i) => { vst[2 * i] = v & 0xFF; vst[2 * i + 1] = v >> 8; });
  segs.push([L.VSTALL, vst]);
  segs.push([L.ROMWS, Uint8Array.from(D.waitstates.rom)]);
  segs.push([L.ROMWSS, Uint8Array.from(D.waitstates.romSeq)]);
  segs.push([L.DMAOFF, Uint8Array.from(D.dmaOffset.map((v) => v & 0xFF))]);
  segs.push([L.PRESCALE, Uint8Array.from(D.timerPrescale)]);
  segs.push([L.SIOCYC, u32le(D.sioCycles)]);
  segs.push([L.DEADBEEF, Uint8Array.from(D.deadbeef)]);
  const e2 = new Uint8Array(256);
  const dv = new DataView(e2.buffer);
  D.exp2fTab.forEach((h, i) => dv.setBigUint64(8 * i, BigInt(h), true));
  segs.push([L.EXP2FTAB, e2]);
  segs.push([video.SINTAB, Buffer.from(D.sintab, "base64")]);
  // base waitstates (GBA_BASE_WAITSTATES*); WAITCNT/EWRAM adjust at init
  const ws = new Uint8Array(1024);
  for (let i = 0; i < 16; i++) {
    ws[i] = D.waitstates.nonseq16[i]; ws[256 + i] = D.waitstates.seq16[i];
    ws[512 + i] = D.waitstates.nonseq32[i]; ws[768 + i] = D.waitstates.seq32[i];
  }
  segs.push([L.WS, ws]);
  segs.push([L.ROM, img]);
  return segs;
}

/** Interpreter over one handler table (the nested-block dispatch). */
function interpThumb() {
  const names = [...new Set(THUMB_TABLE)];
  const idx = new Map(names.map((n, i) => [n, i]));
  const targets = THUMB_TABLE.map((n) => `$h${idx.get(n)}`).join(" ");
  let body = `(br_table ${targets} (i32.shr_u (local.get $op) (i32.const 6)))`;
  names.forEach((n, i) => {
    body = `(block $h${i} ${body}) ${thumb(n, new G(false, { thumb: true }))} (br $end)`;
  });
  return `
  (func $interp_thumb (param $opx i32)
    ${localDecls()}
    (local.set $op (local.get $opx))
    (block $end ${body}))`;
}

function interpArm() {
  const names = [...new Set(ARM_TABLE)];
  const idx = new Map(names.map((n, i) => [n, i]));
  const targets = ARM_TABLE.map((n) => `$h${idx.get(n)}`).join(" ");
  let body = `(br_table ${targets} (i32.or (i32.and (i32.shr_u (local.get $op) (i32.const 16)) (i32.const 0xFF0)) `
    + "(i32.and (i32.shr_u (local.get $op) (i32.const 4)) (i32.const 15))))";
  names.forEach((n, i) => {
    body = `(block $h${i} ${body}) ${arm(n, new G(false))} (br $end)`;
  });
  return `
  (func $interp_arm (param $opx i32)
    ${localDecls()}
    (local.set $op (local.get $opx))
    (block $end ${body}))`;
}

/** conditionLut[cond] & (1 << (NZCV)) */
function condOk(condlut) {
  return `
  (func $cond_ok (param $c i32) (result i32)
    (local $f i32)
    (local.set $f (i32.or (i32.or (i32.shl (global.get $n) (i32.const 3)) (i32.shl (global.get $z) (i32.const 2)))
                          (i32.or (i32.shl (global.get $c) (i32.const 1)) (global.get $v))))
    (i32.and (i32.shr_u (i32.load16_u (i32.add (i32.const ${condlut}) (i32.shl (local.get $c) (i32.const 1))))
                        (local.get $f)) (i32.const 1)))`;
}

/** Static body of one Thumb opcode. */
function thumbBody(op, brk) {
  let b = thumb(THUMB_TABLE[op >> 6], new G(true, { op, thumb: true }));
  if (op === brk) b = "";
  if (b.includes("(local.get $op)")) b = `(local.set $op (i32.const ${op}))` + b;
  return b;
}

/** Static body of one ARM word. */
function armBody(op) {
  const c = op >>> 28;
  if (c === 15) return ""; // never executes (conditionLut[NV] = 0)
  let b = arm(ARM_TABLE[armIndex(op)], new G(true, { op }));
  if (b.includes("(local.get $op)")) b = `(local.set $op (i32.const ${op}))` + b;
  if (c !== 14) b = `(if (call $cond_ok (i32.const ${c})) (then ${b}))`;
  return b;
}

/**
 * Sharded br_table dispatch over arm ids: yields WAT text pieces.
 * @param {string} prefix @param {number} count @param {(i: number) => string} bodyOf
 */
function* shards(prefix, count, bodyOf) {
  const nsh = Math.ceil(count / SHARD);
  const decls = localDecls();
  for (let si = 0; si < nsh; si++) {
    const lo = si * SHARD, n = Math.min(SHARD, count - lo);
    const parts = [`\n  (func $${prefix}${si} (param $id i32)\n    ${decls}\n    (block $end `];
    // nested blocks: innermost holds the br_table
    let s = "";
    for (let i = n - 1; i >= 0; i--) s += `(block $a${i} `;
    parts.push(s);
    const t = [];
    for (let i = 0; i < n; i++) t.push(`$a${i}`);
    parts.push(`(br_table ${t.join(" ")} $a${n - 1} (local.get $id))`);
    for (let i = 0; i < n; i++) parts.push(`)\n    ${bodyOf(lo + i)} (br $end)`);
    parts.push("))");
    yield parts.join("");
  }
  const top = [];
  for (let i = 0; i < nsh; i++) top.push(`$s${i}`);
  let body = `(br_table ${top.join(" ")} $s${nsh - 1} (i32.shr_u (local.get $id) (i32.const ${Math.log2(SHARD)})))`;
  for (let i = 0; i < nsh; i++) {
    body = `(block $s${i} ${body}) (call $${prefix}${i} (i32.and (local.get $id) `
      + `(i32.const ${SHARD - 1}))) (return)`;
  }
  yield `\n  (func $${prefix} (param $id i32)\n    ${body})\n`;
}

/**
 * Emit the whole module as WAT text chunks.
 * @param {Uint8Array} rom
 * @param {GbaOptions} [opts]
 * @returns {AsyncGenerator<string>}
 */
export async function* emitWat(rom, opts = {}) {
  const IMG = toBytes(rom);
  const d = describe(IMG, opts);
  if (!d.supported) throw new Error(`gba recompile refused: ${d.refusal}`);
  const staticRom = d.staticArms;
  const brk = opts.breakThumb == null || opts.breakThumb === "" ? -1
    : typeof opts.breakThumb === "number" ? opts.breakThumb : parseInt(String(opts.breakThumb), 16);
  const L = d.memory;
  setRegs(L.REGS);
  const ROMLEN = IMG.length;
  let THUMB_DISPATCH, ARM_STATIC, AHASH_FN;
  if (staticRom) {
    // ROM regions 8-13 (the three waitstate mirrors), within the image
    const romchk = `(i32.and (i32.lt_u (i32.sub (i32.shr_u (local.get $e) (i32.const 24)) (i32.const 8)) (i32.const 6)) `
      + `(i32.lt_u (i32.and (local.get $e) (i32.const ${romMask(ROMLEN)})) (i32.const ${ROMLEN})))`;
    THUMB_DISPATCH = "(global.set $nstatic (i32.add (global.get $nstatic) (i32.const 1))) "
      + "(call $sthumb (if (result i32) (local.get $ram) (then (local.get $pw)) (else (call $fetch16 (local.get $e)))))";
    ARM_STATIC = `
        (local.set $op (i32.const -1))
        (if ${romchk}
          (then (local.set $op (i32.load (i32.add (i32.const ${L.ATAB})
                  (i32.shl (i32.shr_u (i32.and (local.get $e) (i32.const ${romMask(ROMLEN)})) (i32.const 2)) (i32.const 2))))))
          (else (if (i32.eqz (i32.shr_u (local.get $e) (i32.const 24)))
            (then (local.set $op (i32.load (i32.add (i32.const ${L.BTAB})
                    (i32.and (local.get $e) (i32.const 0x3FFC))))))
            (else (local.set $op (call $ahash_find (if (result i32) (local.get $ram) (then (local.get $pw)) (else (call $fetch32 (local.get $e))))))))))
        (if (i32.ge_s (local.get $op) (i32.const 0))
          (then (global.set $nstatic (i32.add (global.get $nstatic) (i32.const 1)))
                (global.set $cc (i32.add (i32.const 1) (global.get $aseq32)))
                (call $sarm (local.get $op))
                (global.set $cycles (i32.add (global.get $cycles) (global.get $cc)))
                (return)))
        (global.set $ninterp (i32.add (global.get $ninterp) (i32.const 1)))`;
    AHASH_FN = `
  ;; ARM word -> compiled arm id, or -1 (open addressing, id+1 stored, 0 = empty)
  (func $ahash_find (param $w i32) (result i32)
    (local $s i32) (local $p i32) (local $id i32)
    (local.set $s (i32.shr_u (i32.mul (local.get $w) (i32.const 0x9E3779B1)) (i32.const ${32 - L.AHASH_BITS})))
    (loop $l
      (local.set $p (i32.add (i32.const ${L.AHASH}) (i32.shl (local.get $s) (i32.const 3))))
      (local.set $id (i32.load offset=4 (local.get $p)))
      (if (i32.eqz (local.get $id)) (then (return (i32.const -1))))
      (if (i32.eq (i32.load (local.get $p)) (local.get $w))
        (then (return (i32.sub (local.get $id) (i32.const 1)))))
      (local.set $s (i32.and (i32.add (local.get $s) (i32.const 1)) (i32.const ${(1 << L.AHASH_BITS) - 1})))
      (br $l))
    (i32.const -1))`;
  } else {
    THUMB_DISPATCH = "(call $interp_thumb (if (result i32) (local.get $ram) (then (local.get $pw)) (else (call $fetch16 (local.get $e)))))";
    ARM_STATIC = "(global.set $ninterp (i32.add (global.get $ninterp) (i32.const 1)))";
    AHASH_FN = "";
  }
  const ovr = findOverride(d.gameCode, IMG);
  const savetype = ovr.savetype;
  const idle = d.idleLoop;
  const REGS = L.REGS, IO = L.IO, PROBE = L.PROBE, CKPT = L.CKPT, TRACE = L.TRACE, ABI = L.ABI;
  const pages = d.memoryPages;
  const FB_W = video.FB_W, FB_H = video.FB_H;
  // GBA A and B from the wasmcart pad. POSITIONAL (the wasmcart/W3C
  // convention, and what the wasmcart host's input translation assumes):
  // the east face button (WC_BTN_B, bit 1) is the GBA's A, south (WC_BTN_A,
  // bit 0) is B, so one romdev input name presses the same physical button
  // on the cart and on mGBA. buttons:'byName' keeps the earlier emitter's
  // reading (WC bit 0 = GBA A) and emits the Python emitter's exact text.
  const PAD_AB = d.buttons === "byName" ? "(i32.and (local.get $b) (i32.const 3))"
    : "(i32.or (i32.and (i32.shr_u (local.get $b) (i32.const 1)) (i32.const 1)) (i32.and (i32.shl (local.get $b) (i32.const 1)) (i32.const 2)))";

  yield `(module\n  (memory (export "memory") ${pages})`;
  yield "\n" + sysWat(L, ROMLEN, idle, savetype);
  yield "\n" + gpioWat(L, ovr.hardware, !!ovr.vba);
  yield "\n" + swiWat(L);
  yield "\n" + video.colorWat();
  yield "\n" + video.renderWat();
  yield "\n" + condOk(L.CONDLUT);
  yield "\n" + interpThumb();
  yield "\n" + interpArm();
  yield "\n" + mainWat();
  const A = audioLayout({ END: L.AUD });
  yield "\n" + audioWat(L, A, EV_SAMPLE, { trace: !!opts.audioTrace });
  for (const [addr, data] of audioData(A)) {
    yield `\n  (data (i32.const ${addr}) "`;
    yield* watBytesChunks(data);
    yield "\")";
  }
  for (const [addr, data] of dataSegments(L, IMG)) {
    yield `\n  (data (i32.const ${addr}) "`;
    yield* watBytesChunks(data);
    yield "\")";
  }
  const cl = new Uint8Array(32);
  MGBA_DATA.conditionLut.forEach((v, i) => { cl[2 * i] = v & 0xFF; cl[2 * i + 1] = v >> 8; });
  yield `\n  (data (i32.const ${L.CONDLUT}) "${watBytes(cl)}")`;

  if (staticRom) {
    yield* shards("sthumb", 0x10000, (op) => thumbBody(op, brk));
    // ARM: every ROM and BIOS word, identical bodies sharing one arm id
    // (ids in order of first appearance over the sorted unique words).
    const { words, bios } = armWords(IMG);
    const uniq = uniqueWords(words, bios);
    const idOf = new Int32Array(uniq.length);
    /** @type {Map<string, number>} */
    const byKey = new Map();
    /** @type {number[]} */
    const firstOp = [];
    for (let i = 0; i < uniq.length; i++) {
      const b = armBody(uniq[i]);
      const key = createHash("sha1").update(b, "latin1").digest("base64");
      let k = byKey.get(key);
      if (k === undefined) {
        k = firstOp.length;
        byKey.set(key, k);
        firstOp.push(uniq[i]);
      }
      idOf[i] = k;
    }
    byKey.clear();
    if (opts.stats) Object.assign(opts.stats, { thumbArms: 0x10000, armArms: firstOp.length, uniqueArmWords: uniq.length,
      arms: 0x10000 + firstOp.length, lowered: 0x10000 + firstOp.length, trapped: 0 });
    yield* shards("sarm", firstOp.length, (id) => armBody(firstOp[id]));
    const find = (w) => {
      let lo = 0, hi = uniq.length - 1;
      while (lo <= hi) {
        const m = (lo + hi) >> 1;
        if (uniq[m] < w) lo = m + 1; else if (uniq[m] > w) hi = m - 1; else return idOf[m];
      }
      throw new Error("gba recompile: word missing from the unique set");
    };
    const atab = new Uint32Array(words.length);
    for (let i = 0; i < words.length; i++) atab[i] = find(words[i]);
    const btab = new Uint32Array(bios.length);
    for (let i = 0; i < bios.length; i++) btab[i] = find(bios[i]);
    const k = L.AHASH_BITS;
    const ah = new Uint32Array(2 << k);
    const kmask = (1 << k) - 1;
    for (let i = 0; i < uniq.length; i++) {
      const w = uniq[i];
      let sl = ahashSlot(w, k);
      while (ah[2 * sl + 1]) sl = (sl + 1) & kmask;
      ah[2 * sl] = w; ah[2 * sl + 1] = idOf[i] + 1;
    }
    yield `\n  (data (i32.const ${L.ATAB}) "`;
    yield* watBytesChunks(new Uint8Array(atab.buffer));
    yield `")\n  (data (i32.const ${L.BTAB}) "`;
    yield* watBytesChunks(new Uint8Array(btab.buffer));
    yield `")\n  (data (i32.const ${L.AHASH}) "`;
    yield* watBytesChunks(new Uint8Array(ah.buffer));
    yield "\")";
  }
  yield "\n)\n";

  function mainWat() {
    return `
  (global $trapped (mut i32) (i32.const 0))
  (global $trappc (mut i32) (i32.const 0))
  (global $steps (mut i32) (i32.const 0))
  (global $nstatic (mut i32) (i32.const 0))
  (global $ninterp (mut i32) (i32.const 0))
  ${AHASH_FN}
  (global $started (mut i32) (i32.const 0))

  (func $trap_invalid (param $a i32)
    (if (i32.eqz (global.get $trapped))
      (then (global.set $trapped (i32.const 1)) (global.set $trappc (local.get $a))))
    (global.set $nextEvent (global.get $cycles)))

  ;; renderer hooks (the software renderer's writeVideoRegister/finishFrame)
  (func $video_reg_written (param $a i32)
    (if (i32.and (i32.ge_u (local.get $a) (i32.const 0x28)) (i32.lt_u (local.get $a) (i32.const 0x30)))
      (then (call $gba_aff_reload (i32.const 2))))
    (if (i32.and (i32.ge_u (local.get $a) (i32.const 0x38)) (i32.lt_u (local.get $a) (i32.const 0x40)))
      (then (call $gba_aff_reload (i32.const 3)))))
  (func $frame_finish)

  ;; One instruction (ARMStep / ThumbStep).
  (func $step
    (local $e i32) (local $op i32) (local $ti i32) (local $ram i32) (local $pw i32)
    (local.set $e (global.get $pc))
    (global.set $exec (local.get $e))
    ;; code in RAM runs what the pipeline fetched ($pipe_word); ROM and BIOS
    ;; code by address
    (local.set $ram (call $pipe_region (local.get $e)))
    (if (local.get $ram)
      (then (local.set $pw (call $pipe_word (local.get $e))))
      (else (global.set $pfa0 (i32.const -1))))
    ;; trace hook: record the instruction about to execute, as the native
    ;; reference's hook does (pc, thumb, time, r0-r15 with r15 = gprs[PC]
    ;; before the step, cpsr, vcount)
    (if (i32.load (i32.const ${PROBE + 64}))
      (then
        (local.set $ti (i32.load (i32.const ${PROBE + 68})))
        (if (i32.lt_u (local.get $ti) (i32.const ${TRACE_CAP}))
          (then
            (local.set $op (i32.add (i32.const ${TRACE}) (i32.mul (local.get $ti) (i32.const 84))))
            (i32.store (local.get $op) (local.get $e))
            (i32.store offset=4 (local.get $op) (global.get $thumb))
            (i32.store offset=8 (local.get $op) (call $now))
            (memory.copy (i32.add (local.get $op) (i32.const 12)) (i32.const ${REGS}) (i32.const 60))
            (i32.store offset=72 (local.get $op) (i32.add (local.get $e) (if (result i32) (global.get $thumb) (then (i32.const 2)) (else (i32.const 4)))))
            (i32.store offset=76 (local.get $op) (call $pack_cpsr))
            (i32.store offset=80 (local.get $op) (global.get $vcount))
            (i32.store (i32.const ${PROBE + 68}) (i32.add (local.get $ti) (i32.const 1)))))))
    (if (global.get $thumb)
      (then
        (i32.store (i32.const ${REGS + 60}) (i32.add (local.get $e) (i32.const 4)))
        (global.set $pc (i32.add (local.get $e) (i32.const 2)))
        (global.set $cc (i32.add (i32.const 1) (global.get $aseq16)))
        ${THUMB_DISPATCH})
      (else
        (i32.store (i32.const ${REGS + 60}) (i32.add (local.get $e) (i32.const 8)))
        (global.set $pc (i32.add (local.get $e) (i32.const 4)))
        ${ARM_STATIC}
        (local.set $op (if (result i32) (local.get $ram) (then (local.get $pw)) (else (call $fetch32 (local.get $e)))))
        (if (i32.ne (i32.shr_u (local.get $op) (i32.const 28)) (i32.const 14))
          (then (if (i32.eqz (call $cond_ok (i32.shr_u (local.get $op) (i32.const 28))))
            (then (global.set $cycles (i32.add (global.get $cycles) (i32.add (i32.const 1) (global.get $aseq32))))
                  (return)))))
        (global.set $cc (i32.add (i32.const 1) (global.get $aseq32)))
        (call $interp_arm (local.get $op))))
    (global.set $cycles (i32.add (global.get $cycles) (global.get $cc))))

  ;; ARMRunLoop
  (func $run_loop
    (block $d (loop $l
      (br_if $d (i32.ge_s (global.get $cycles) (global.get $nextEvent)))
      (br_if $d (global.get $trapped))
      (call $step)
      (global.set $steps (i32.add (global.get $steps) (i32.const 1)))
      (br $l)))
    (call $process_events))

  ;; _GBACoreRunFrame
  (func $run_frame
    (local $fc i32) (local $start i32)
    (local.set $fc (global.get $frameCounter))
    (local.set $start (call $now))
    (block $d (loop $l
      (br_if $d (i32.ne (global.get $frameCounter) (local.get $fc)))
      (br_if $d (i32.ge_s (i32.sub (call $now) (local.get $start)) (i32.const ${VIDEO_TOTAL_LENGTH + 1232})))
      (br_if $d (global.get $trapped))
      (call $run_loop)
      (br $l))))

  (func (export "wc_get_info") (result i32)
    (i32.store (i32.const ${ABI}) (i32.const ${WC_ABI_VERSION}))
    (i32.store (i32.const ${ABI + 4}) (i32.const ${FB_W}))
    (i32.store (i32.const ${ABI + 8}) (i32.const ${FB_H}))
    (i32.store (i32.const ${ABI + 12}) (i32.const ${L.FB}))
    ;; inputPtr and timePtr must be real addresses: the host writes through
    ;; both every frame with no zero check.
    (i32.store (i32.const ${ABI + 28}) (i32.const ${ABI + 0x100}))
    (i32.store (i32.const ${ABI + 40}) (i32.const ${ABI + 0x180}))
    ${audioInfoWat(audioLayout({ END: L.AUD }), ABI)}
    (i32.const ${ABI}))

  (func (export "wc_set_input") (param $m i32))

  ;; GBAReset + ARMReset + GBAMemoryReset/VideoReset/IOInit/TimerInit
  ;; (no BIOS file, so the HLE BIOS runs from the reset vector)
  (func (export "wc_init")
    (local $i i32)
    (memory.fill (i32.const ${L.SAVE}) (i32.const 0xFF) (i32.const 0x20000))
    ;; ARMReset: system mode, ARM, pc 0; GBAReset sets the three stacks
    (global.set $priv (i32.const 0x1F))
    (global.set $ctl (i32.const 0x1F))
    (global.set $thumb (i32.const 0))
    (i32.store (i32.const ${L.BANK + 2 * 28}) (i32.const 0x03007FA0))    ;; IRQ sp
    (i32.store (i32.const ${L.BANK + 3 * 28}) (i32.const 0x03007FE0))    ;; SVC sp
    (i32.store (i32.const ${REGS + 52}) (i32.const 0x03007F00))
    (i32.store (i32.const ${REGS + 60}) (i32.const 4))
    (global.set $pc (i32.const 0))
    ;; GBAMemoryReset
    (call $adjust_waitstates (i32.const 0))
    (call $adjust_ewram (i32.const 0x0D00))
    (global.set $areg (i32.const -1))
    (global.set $aseq16 (i32.const 0)) (global.set $anon16 (i32.const 0))
    (global.set $aseq32 (i32.const 0)) (global.set $anon32 (i32.const 0))
    (global.set $prefetch (i32.const 0))
    (i32.store (call $dp (i32.const 0) (i32.const 12)) (i32.const 0x4000))
    (i32.store (call $dp (i32.const 1) (i32.const 12)) (i32.const 0x4000))
    (i32.store (call $dp (i32.const 2) (i32.const 12)) (i32.const 0x4000))
    (i32.store (call $dp (i32.const 3) (i32.const 12)) (i32.const 0x10000))
    ;; GBAVideoReset (no full BIOS): line 0x7E, first HBlank in 120 cycles
    (global.set $vcount (i32.const 0x7E))
    (global.set $vcb (i32.const 0))
    (call $schedule (i32.const ${EV_VIDEO}) (i32.const 120))
    ;; GBAAudioReset: PSG frame sequencer and sample events at 0
    (call $schedule (i32.const ${EV_FRAME}) (i32.const 0))
    (call $schedule (i32.const ${EV_SAMPLE}) (i32.const 0))
    (call $au_reset)
    ;; GBAIOInit
    (i32.store16 (i32.const ${IO}) (i32.const 0x80))
    (i32.store16 (i32.const ${IO + 0x134}) (i32.const 0x8000))
    (i32.store16 (i32.const ${IO + 0x130}) (i32.const 0x3FF))
    (i32.store16 (i32.const ${IO + 0x88}) (i32.const 0x200))
    (i32.store16 (i32.const ${IO + 0x20}) (i32.const 0x100))
    (i32.store16 (i32.const ${IO + 0x26}) (i32.const 0x100))
    (i32.store16 (i32.const ${IO + 0x30}) (i32.const 0x100))
    (i32.store16 (i32.const ${IO + 0x36}) (i32.const 0x100))
    (i32.store16 (i32.const ${IO + 0x210}) (i32.const 0x20))
    (i32.store16 (i32.const ${IO + 0x212}) (i32.const 0xD00))
    (i32.store16 (i32.const ${IO + 6}) (i32.const 0x7E))
    (i32.store16 (i32.const ${IO + 0x300}) (i32.const 1))
    (global.set $nextEvent (i32.const 0)))

  (func (export "wc_render")
    (local $b i32) (local $k i32) (local $f i32)
    ;; libretro -> GBA keys: the host writes the wasmcart pad word (A B X Y
    ;; L R Start Select Up Down Left Right); KEYINPUT order is A B Select
    ;; Start Right Left Up Down R L.
    (local.set $b (i32.load16_u (i32.const ${ABI + 0x100})))
    ;; the libretro port's solar level buttons (gpio.js $lux_input)
    (call $lux_input (local.get $b))
    (local.set $k (i32.or (i32.or (i32.or ${PAD_AB}
                                          (i32.shl (i32.and (i32.shr_u (local.get $b) (i32.const 7)) (i32.const 1)) (i32.const 2)))
                                  (i32.or (i32.shl (i32.and (i32.shr_u (local.get $b) (i32.const 6)) (i32.const 1)) (i32.const 3))
                                          (i32.shl (i32.and (i32.shr_u (local.get $b) (i32.const 11)) (i32.const 1)) (i32.const 4))))
                          (i32.or (i32.or (i32.shl (i32.and (i32.shr_u (local.get $b) (i32.const 10)) (i32.const 1)) (i32.const 5))
                                          (i32.shl (i32.and (i32.shr_u (local.get $b) (i32.const 8)) (i32.const 1)) (i32.const 6)))
                                  (i32.or (i32.or (i32.shl (i32.and (i32.shr_u (local.get $b) (i32.const 9)) (i32.const 1)) (i32.const 7))
                                                  (i32.shl (i32.and (i32.shr_u (local.get $b) (i32.const 5)) (i32.const 1)) (i32.const 8)))
                                          (i32.shl (i32.and (i32.shr_u (local.get $b) (i32.const 4)) (i32.const 1)) (i32.const 9))))))
    (if (i32.eqz (global.get $started))
      (then
        (global.set $started (i32.const 1))
        (global.set $keysActive (i32.const 0))
        (local.set $f (i32.const 0))
        (block $wd (loop $wl
          (br_if $wd (i32.ge_u (local.get $f) (i32.const ${WARMUP_FRAMES})))
          (call $test_keypad_irq)
          (call $au_frame_begin)
          (call $run_frame)
          (call $au_frame_end)
          (local.set $f (i32.add (local.get $f) (i32.const 1)))
          (br $wl)))))
    (global.set $keysActive (local.get $k))
    (call $test_keypad_irq)
    (call $au_frame_begin)
    (call $run_frame)
    (call $au_frame_end)
    (call $checkpoint))

  ;; per-frame checkpoint, laid out like the native reference's
  ;; gbatrace_checkpoint for a direct diff
  (func $checkpoint
    (i32.store (i32.const ${CKPT}) (call $now))
    (memory.copy (i32.const ${CKPT + 4}) (i32.const ${REGS}) (i32.const 64))
    (i32.store (i32.const ${CKPT + 68}) (call $pack_cpsr))
    (i32.store (i32.const ${CKPT + 72}) (global.get $spsr))
    (i32.store (i32.const ${CKPT + 76}) (global.get $halted))
    (i32.store (i32.const ${CKPT + 80}) (call $fnv (i32.const ${L.EWRAM}) (i32.const 0x40000)))
    (i32.store (i32.const ${CKPT + 84}) (call $fnv (i32.const ${L.IWRAM}) (i32.const 0x8000)))
    (i32.store (i32.const ${CKPT + 88}) (call $fnv (i32.const ${L.VRAM}) (i32.const 0x18000)))
    (i32.store (i32.const ${CKPT + 92}) (call $fnv (i32.const ${L.PAL}) (i32.const 0x400)))
    (i32.store (i32.const ${CKPT + 96}) (call $fnv (i32.const ${L.OAM}) (i32.const 0x400)))
    (i32.store (i32.const ${CKPT + 100}) (call $fnv (i32.const ${IO}) (i32.const 0x60)))
    (i32.store (i32.const ${CKPT + 104}) (global.get $vcount))
    (i32.store (i32.const ${CKPT + 108}) (global.get $cycles))
    (i32.store (i32.const ${CKPT + 112}) (global.get $nextEvent))
    (i32.store (i32.const ${PROBE}) (global.get $steps))
    (i32.store (i32.const ${PROBE + 4}) (global.get $trapped))
    (i32.store (i32.const ${PROBE + 8}) (global.get $trappc))
    (i32.store (i32.const ${PROBE + 12}) (global.get $pc))
    (i32.store (i32.const ${PROBE + 16}) (global.get $frameCounter))
    (i32.store (i32.const ${PROBE + 20}) (global.get $nstatic))
    (i32.store (i32.const ${PROBE + 24}) (global.get $ninterp)))

  (func $fnv (param $p i32) (param $n i32) (result i32)
    (local $h i32) (local $e i32)
    (local.set $h (i32.const 0x811C9DC5))
    (local.set $e (i32.add (local.get $p) (local.get $n)))
    (block $d (loop $l
      (br_if $d (i32.ge_u (local.get $p) (local.get $e)))
      (local.set $h (i32.mul (i32.xor (local.get $h) (i32.load8_u (local.get $p))) (i32.const 16777619)))
      (local.set $p (i32.add (local.get $p) (i32.const 1)))
      (br $l)))
    (local.get $h))
`;
  }
}
